const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define points for East Midlands, Northeast England, and Eastern Scotland
  const locations = ee.Geometry.MultiPoint([
    [-1.15, 52.95], // East Midlands (Nottingham)
    [-1.61, 54.97], // Northeast England (Newcastle)
    [-2.10, 57.15]  // Eastern Scotland (Aberdeen)
  ]);

  const recentStartDate = '2023-10-01';
  const recentEndDate = '2024-01-04'; // EE will include Jan 2024 imagery

  const historicalStartYear = 1991;
  const historicalEndYear = 2020;
  const months = [10, 11, 12, 1]; // October, November, December, January

  const collectionName = 'ECMWF/ERA5-LAND/MONTHLY_AGGR';
  const bandName = 'total_precipitation_sum';

  // 2. Data Acquisition
  // Recent rainfall data
  const recentCollection = ee.ImageCollection(collectionName)
    .filterDate(recentStartDate, recentEndDate)
    .select(bandName);

  // Historical rainfall data for the specified months
  const historicalCollection = ee.ImageCollection(collectionName)
    .filter(ee.Filter.calendarRange(historicalStartYear, historicalEndYear, 'year'))
    .filter(ee.Filter.inList('month', months))
    .select(bandName);

  // Check for data availability
  const recentSize = recentCollection.size().getInfo();
  const historicalSize = historicalCollection.size().getInfo();

  if (recentSize === 0 || historicalSize === 0) {
    console.log(`Recent image count: ${recentSize}`);
    console.log(`Historical image count: ${historicalSize}`);
    console.log("No images found for one or both periods.");
    console.log("A: No");
    return;
  }

  // 3. Processing & Calculation
  // Calculate total recent rainfall (Oct 2023 - Jan 2024)
  const recentTotal = recentCollection.sum();

  // Calculate the average monthly rainfall for the historical period
  const historicalMean = historicalCollection.mean();
  // Multiply by 4 to get the total for the 4-month period for a fair comparison
  const historicalTotalForPeriod = historicalMean.multiply(4);

  const reducer = ee.Reducer.mean();
  const scale = 1000;

  // Reduce regions to get mean values over the three points
  const recentRainfallValue = recentTotal.reduceRegion({
    reducer: reducer,
    geometry: locations,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName);

  const historicalRainfallValue = historicalTotalForPeriod.reduceRegion({
    reducer: reducer,
    geometry: locations,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName);

  // Retrieve the results
  const recentVal = recentRainfallValue.getInfo();
  const histVal = historicalRainfallValue.getInfo();

  // 4. Validation
  if (recentVal === null || histVal === null) {
    console.log(`Recent Rainfall: ${recentVal}`);
    console.log(`Historical Average Rainfall: ${histVal}`);
    console.log("Calculation failed, result is null.");
    console.log("C3: Calculation Failure");
    return;
  }

  // 5. Evidence and Final Answer
  console.log(`Recent rainfall (Oct 2023 - Jan 2024): ${recentVal.toFixed(4) * 1000} mm`);
  console.log(`Historical average (1991-2020): ${histVal.toFixed(4) * 1000} mm`);
  console.log(`Recent Image Count: ${recentSize}`);
  console.log(`Historical Image Count: ${historicalSize}`);

  if (recentVal > histVal) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
  }
}

initEE();
